                                                                                                                                                                                                                                                                                > 
                                                                                                                                                                                                                                                                                  > bg_baseline_errors_all <- comparison_data %>%
                                                                                                                                                                                                                                                                                  +   transmute(
                                                                                                                                                                                                                                                                                    +     method = "BG Baseline",
